n = 260**135
count = 0
while n >= 30 and count < 2025:
    n = f(n)
    count += 1
print(f"After {count} steps, n is {n}")

remaining = 2025 - count
for _ in range(remaining):
    n = f(n)
print(f"Final n: {n}")

